  const main = dir + "/字面量.md";
  let cur = "";
  try { cur = fsz.readFileSync(main, "utf8"); } catch (e) { return null; }
  const n = (cur.match(/^- /gm) || []).length;
  if (n < LITERALS_ROTATE_AT) return null;
