      NEURO_USER_MOVED = false;   // [视角] 换图（筛选/聚焦/重置视图）才重新允许自动取景
      NEURO_AUTO_CAM = null;      // [视角] 同时清掉"上次自动取景位置"，否则位置比对会误判为新图已被用户改过
