            const out = existing.slice(0, idx) + it.new_string + existing.slice(idx + it.old_string.length);
            let _f = null; for (const _l of out.split("\n")) _f = fenceStep(_l, _f)[0];
            if (_f !== null) { skipped.push(it.rel + "(edit结果围栏未闭合)"); continue; }
